"""Exact rational evaluation of the fork profile and the four channel leakages.

The fork profile is  Phi(t, n) = t^n / (1 + t + ... + t^n).  For a rational
argument t = a/b with 0 <= a < b it has the closed rational form

    Phi(a/b, n) = a^n (b - a) / (b^(n+1) - a^(n+1)),

which is evaluated below in exact integer arithmetic.  The four fork channels
of an (n+1)-bit Bernoulli(p) fork are the profile at four parameters:

    AND   -> p            OR    -> 1 - p
    XOR   -> (1 - 2p)^2   count -> 1   (giving exactly 1/(n+1)).
"""

from __future__ import annotations

from fractions import Fraction
from typing import Dict, List, Tuple


def phi_exact(t: Fraction, n: int) -> Fraction:
    """Phi(t, n) = t^n / (1 + t + ... + t^n), in exact rational arithmetic.

    Uses the closed form a^n (b-a) / (b^{n+1} - a^{n+1}) when t < 1, the exact
    value 1/(n+1) when t == 1, and the defining sum otherwise.  Cost: O(log n)
    big-integer multiplications for the powers, on integers of O(n log b) bits.
    """
    if t < 0:
        raise ValueError("the profile is defined for non-negative parameters")
    if t == 1:
        return Fraction(1, n + 1)
    a, b = t.numerator, t.denominator
    if t < 1:
        return Fraction(a ** n * (b - a), b ** (n + 1) - a ** (n + 1))
    # t > 1: same algebra with the sign of the denominator reversed.
    return Fraction(a ** n * (a - b), a ** (n + 1) - b ** (n + 1))


def channel_parameters(p: Fraction) -> Dict[str, Fraction]:
    """The four size-independent channel parameters of a Bernoulli(p) fork."""
    return {"A": p, "g": 1 - p, "X": (1 - 2 * p) ** 2, "Is": Fraction(1)}


def channel_leakages(p: Fraction, n: int) -> Dict[str, Fraction]:
    """Exact leakages of AND / OR / XOR / split count for an (n+1)-bit fork."""
    return {name: phi_exact(t, n) for name, t in channel_parameters(p).items()}


def channel_table(p: Fraction, n_max: int) -> List[Tuple[int, Dict[str, Fraction]]]:
    """The complete exact channel table for n = 1 .. n_max."""
    return [(n, channel_leakages(p, n)) for n in range(1, n_max + 1)]


if __name__ == "__main__":
    p = Fraction(1, 3)
    for n, row in channel_table(p, 25):
        if n in (1, 5, 8, 12, 24, 25):
            entries = "  ".join(f"{k}={float(v):.6e}" for k, v in row.items())
            print(f"n={n:>3}  {entries}")
    print()
    print("exact 25-bit entries (n = 24, p = 1/3):")
    for name, value in channel_leakages(Fraction(1, 3), 24).items():
        print(f"  {name:>3} = {value}")

