function FORK-WEIGHT(p, x):
    w <- 1
    for each bit b of x: w <- w * (p if b = 1 else 1 - p)
    return w                                     # exact rational

function EXPECTATION(p, F, N):
    total <- 0
    for x in {0,1}^N: total <- total + FORK-WEIGHT(p, x) * F(x)
    return total

function CHECK-NORMALISATION(p, N):
    return EXPECTATION(p, x -> 1, N) = 1         # must be exactly 1

function COVARIANCE(p, F, G, N):
    return EXPECTATION(p, F*G, N) - EXPECTATION(p, F, N) * EXPECTATION(p, G, N)

function LEAKAGE(p, F, N):                       # about the bit x_0
    vF <- COVARIANCE(p, F, F, N);  v0 <- COVARIANCE(p, x_0, x_0, N)
    if vF = 0 or v0 = 0: return 0
    return COVARIANCE(p, x_0, F, N)^2 / (v0 * vF)

function CERTIFY(p, n_max):
    for n = 1 .. n_max:
        assert CHECK-NORMALISATION(p, n+1)
        for (channel, readout, parameter) in {AND:p, OR:1-p, XOR:(1-2p)^2, count:1}:
            assert LEAKAGE(p, readout, n+1) = PHI(parameter, n)

