"""Brute-force certification of fork leakage by exhaustive exact enumeration.

This is the reference implementation against which every closed form is
checked.  It enumerates all 2^N bit patterns of an N-bit fork, accumulates the
exact product weights, and forms the covariance and variances directly in
rational arithmetic.  Its purpose is not speed but trust: it proves the
normalisation sum_x w(x) = 1 numerically-exactly, and it exposes the two silent
failure modes that corrupt floating-point tabulations of the same quantities
(unnormalised weights, and marginals inconsistent with the joint).

Complexity: O(2^N * N) exact rational operations, so usable to about N = 16.
"""

from __future__ import annotations

from fractions import Fraction
from itertools import product
from typing import Callable, List, Tuple

Bits = Tuple[int, ...]
Readout = Callable[[Bits], Fraction]


def fork_weight(p: Fraction, x: Bits) -> Fraction:
    """Exact product weight of a bit pattern under independent Bernoulli(p)."""
    w = Fraction(1)
    for b in x:
        w *= p if b else (1 - p)
    return w


def expectation(p: Fraction, f: Readout, n_bits: int) -> Fraction:
    """Exact expectation of a readout over the whole 2^n_bits pattern space."""
    total = Fraction(0)
    for x in product((0, 1), repeat=n_bits):
        total += fork_weight(p, x) * f(x)
    return total


def check_normalisation(p: Fraction, n_bits: int) -> bool:
    """Certify that the weights sum to exactly one (no unnormalised weighting)."""
    return expectation(p, lambda _x: Fraction(1), n_bits) == 1


def covariance(p: Fraction, f: Readout, g: Readout, n_bits: int) -> Fraction:
    """Exact Cov(f, g) = E[fg] - E[f] E[g]."""
    return (expectation(p, lambda x: f(x) * g(x), n_bits)
            - expectation(p, f, n_bits) * expectation(p, g, n_bits))


def leakage(p: Fraction, f: Readout, n_bits: int) -> Fraction:
    """Squared Pearson correlation between the designated bit x_0 and a readout."""
    x0: Readout = lambda x: Fraction(x[0])
    var_f = covariance(p, f, f, n_bits)
    var_x0 = covariance(p, x0, x0, n_bits)
    if var_f == 0 or var_x0 == 0:
        return Fraction(0)
    return covariance(p, x0, f, n_bits) ** 2 / (var_x0 * var_f)


def certify(p: Fraction, n_max: int) -> List[Tuple[int, str, bool]]:
    """Compare brute force with the closed forms for n = 1 .. n_max."""
    def phi(t: Fraction, n: int) -> Fraction:
        return t ** n / sum((t ** k for k in range(n + 1)), Fraction(0))

    readouts = {
        "A": (lambda x: Fraction(all(x)), lambda pp: pp),
        "g": (lambda x: Fraction(any(x)), lambda pp: 1 - pp),
        "X": (lambda x: Fraction(sum(x) % 2), lambda pp: (1 - 2 * pp) ** 2),
        "Is": (lambda x: Fraction(sum(x)), lambda _pp: Fraction(1)),
    }
    out: List[Tuple[int, str, bool]] = []
    for n in range(1, n_max + 1):
        assert check_normalisation(p, n + 1)
        for name, (f, param) in readouts.items():
            out.append((n, name, leakage(p, f, n + 1) == phi(param(p), n)))
    return out


if __name__ == "__main__":
    results = certify(Fraction(1, 3), 8)
    print(f"checks performed: {len(results)};  all agree: {all(r[2] for r in results)}")
    for n, name, ok in results:
        if not ok:
            print(f"  MISMATCH at n={n}, channel {name}")

