function PRODUCT-PARAMETER(p, c1, c0):           # c1 = c(true), c0 = c(false)
    require c1 != c0                             # non-constant coordinate function
    m <- p*c1 + (1-p)*c0                         # first moment
    s <- p*c1^2 + (1-p)*c0^2                     # second moment
    return m^2 / s                               # provably in [0, 1)

function RANK-PRODUCT-READOUTS(p, family):
    scored <- [ (name, PRODUCT-PARAMETER(p, c1, c0)) for (name,c1,c0) in family ]
    sort scored ascending by parameter
    return scored          # valid ranking by leakage at EVERY fork size n >= 1

function CROSSOVER-POSSIBLE(p, readout1, readout2):
    t1 <- PRODUCT-PARAMETER(p, readout1);  t2 <- PRODUCT-PARAMETER(p, readout2)
    signs <- {}
    for n = 1 .. N:
        signs <- signs union { sign( PHI(t1,n) - PHI(t2,n) ) }
    return |signs| > 1                            # provably always false
